import { Context, Contract, Info, Returns, Transaction } from 'fabric-contract-api';
import { AuditLogger } from './audit';

interface AccountState {
  balance: number;
  locked: boolean;
  nonce: number;
  withdrawalCallbacks: string[];
}

interface WithdrawalRequest {
  from: string;
  amount: number;
  timestamp: number;
  callbackContract: string;
}

@Info({ title: 'VaultContract', description: 'Secure vault with audit logging' })
export class VaultContract extends Contract {
  private auditLogger: AuditLogger;
  private processingQueue: Map<string, boolean>;

  constructor() {
    super('VaultContract');
    this.auditLogger = new AuditLogger();
    this.processingQueue = new Map();
  }

  @Transaction()
  public async initAccount(ctx: Context, accountId: string, initialBalance: number): Promise<void> {
    if (typeof accountId !== 'string' || accountId.length === 0) {
      throw new Error('Invalid accountId');
    }
    if (!Number.isFinite(initialBalance) || initialBalance < 0) {
      throw new Error('initialBalance must be a non-negative finite number');
    }
    const state: AccountState = {
      balance: initialBalance,
      locked: false,
      nonce: 0,
      withdrawalCallbacks: []
    };
    await ctx.stub.putState(accountId, Buffer.from(JSON.stringify(state)));
    await this.auditLogger.log(ctx, 'INIT', accountId, { initialBalance });
  }

  @Transaction()
  public async registerCallback(ctx: Context, accountId: string, callbackContract: string): Promise<void> {
    if (typeof callbackContract !== 'string' || callbackContract.length === 0) {
      throw new Error('Invalid callbackContract');
    }
    const stateBytes = await ctx.stub.getState(accountId);
    if (!stateBytes || stateBytes.length === 0) throw new Error('Account not found');
    const state: AccountState = JSON.parse(stateBytes.toString());
    state.withdrawalCallbacks.push(callbackContract);
    await ctx.stub.putState(accountId, Buffer.from(JSON.stringify(state)));
    await this.auditLogger.log(ctx, 'REGISTER_CALLBACK', accountId, { callbackContract });
  }

  @Transaction()
  @Returns('boolean')
  public async withdraw(ctx: Context, accountId: string, amount: number): Promise<boolean> {
    if (!Number.isFinite(amount) || amount <= 0) {
      throw new Error('amount must be a positive finite number');
    }
    const stateBytes = await ctx.stub.getState(accountId);
    if (!stateBytes || stateBytes.length === 0) throw new Error('Account not found');
    const state: AccountState = JSON.parse(stateBytes.toString());

    if (state.locked) {
      await this.auditLogger.log(ctx, 'WITHDRAW_REJECTED_LOCKED', accountId, { amount });
      return false;
    }

    if (state.balance < amount) {
      await this.auditLogger.log(ctx, 'WITHDRAW_REJECTED_INSUFFICIENT', accountId, { amount, balance: state.balance });
      return false;
    }

    // Pre-withdrawal audit with balance snapshot
    const preBalance = state.balance;
    await this.auditLogger.log(ctx, 'WITHDRAW_INITIATED', accountId, {
      amount,
      preBalance,
      nonce: state.nonce
    });

    // Apply withdrawal to state BEFORE callbacks (checks-effects-interactions)
    state.balance -= amount;
    state.nonce += 1;

    await ctx.stub.putState(accountId, Buffer.from(JSON.stringify(state)));

    // Execute callbacks after state update
    const callbackResults = await this.executeWithdrawalCallbacks(
      ctx, accountId, amount, state
    );

    await this.auditLogger.log(ctx, 'WITHDRAW_COMPLETED', accountId, {
      amount,
      postBalance: state.balance,
      nonce: state.nonce,
      callbackResults
    });

    return true;
  }

  private async executeWithdrawalCallbacks(
    ctx: Context,
    accountId: string,
    amount: number,
    currentState: AccountState
  ): Promise<string[]> {
    const results: string[] = [];

    for (const callback of currentState.withdrawalCallbacks) {
      try {
        // Invoke the registered callback contract
        const response = await ctx.stub.invokeChaincode(
          callback,
          ['onWithdrawal', accountId, amount.toString(), currentState.balance.toString()],
          ctx.stub.getChannelID()
        );
        results.push(`${callback}:${response.status}`);
      } catch (err) {
        results.push(`${callback}:error`);
        await this.auditLogger.log(ctx, 'CALLBACK_ERROR', accountId, {
          callback,
          error: (err as Error).message
        });
      }
    }

    return results;
  }

  @Transaction()
  @Returns('number')
  public async getBalance(ctx: Context, accountId: string): Promise<number> {
    const stateBytes = await ctx.stub.getState(accountId);
    if (!stateBytes || stateBytes.length === 0) throw new Error('Account not found');
    const state: AccountState = JSON.parse(stateBytes.toString());
    return state.balance;
  }

  @Transaction()
  public async batchWithdraw(ctx: Context, accountId: string, amounts: number[]): Promise<boolean[]> {
    const results: boolean[] = [];
    for (const amount of amounts) {
      const result = await this.withdraw(ctx, accountId, amount);
      results.push(result);
    }
    return results;
  }
}

export class AuditLogger {
  public async log(ctx: Context, event: string, accountId: string, data: Record<string, any>): Promise<void> {
    const logEntry = {
      timestamp: ctx.stub.getTxTimestamp(),
      txId: ctx.stub.getTxID(),
      event,
      accountId,
      ...data
    };
    const logKey = `AUDIT_${accountId}_${ctx.stub.getTxID()}_${event}`;
    await ctx.stub.putState(logKey, Buffer.from(JSON.stringify(logEntry)));
    ctx.stub.setEvent(event, Buffer.from(JSON.stringify(logEntry)));
  }
}
